/bin/zsh -lc "cat > /private/tmp/r012_dump.py <<'PY'
import zipfile,xml.etree.ElementTree as E,glob
N={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
for f in sorted(glob.glob('*.xlsx')):
 z=zipfile.ZipFile(f); ss=[]
 if 'xl/sharedStrings.xml' in z.namelist():
  ss=[''.join(x.itertext()) for x in E.fromstring(z.read('xl/sharedStrings.xml')).findall('m:si',N)]
 rel={r.attrib['Id']:r.attrib['Target'] for r in E.fromstring(z.read('xl/_rels/workbook.xml.rels'))}
 print('\\nFILE',f)
 for s in E.fromstring(z.read('xl/workbook.xml')).findall('m:sheets/m:sheet',N):
  target=rel[s.attrib['{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id']]; target=target.lstrip('/') if target.startswith('/') else 'xl/'+target
  print('SHEET',s.attrib['name'])
  for row in E.fromstring(z.read(target)).findall('m:sheetData/m:row',N):
   vals=[]
   for c in row:
    v=c.find('m:v',N)
    if v is not None:
     val=ss[int(v.text)] if c.get('t')=='s' else v.text
     vals.append(c.get('r')+'='+str(val))
   if vals:print(' | '.join(vals))
PY
python3 /private/tmp/r012_dump.py > /private/tmp/r012_dump.txt
wc -l /private/tmp/r012_dump.txt"

